        calls = [{"index": i, "id": f"call_{i}", "type": "function",
                  "function": {"name": f"tool{i}", "arguments": "".join(rng.choice(PIECES) for _ in range(rng.randint(0, 6)))}}
                 for i in range(rng.randint(0, 3))]
        frags = []
