            else:
                outs.append(rng.choice(WORDS))
        k = rng.randint(1, 6)
        d = {fn}(convert, prompt, initial_offset=k)
        got = [d.step(t) for t in outs]
        assert got == reference(prompt, outs, k), (seed, trial, prompt, outs, k, got)
        if not convert(outs).endswith("�") and not prompt:
            assert "".join(got) == convert(outs), (prompt, outs, got)

import random, re
def oracle(body):
    lines = re.split(rb"\r\n|\r|\n", body)[:-1]
    out, ev, data, rid, retry, pending = [], None, [], None, None, False
    for raw in lines:
        line = raw.decode()
        if line == "":
            if pending:
                e = {"event": ev, "data": "\n".join(data), "id": rid, "retry": retry}
                if e["data"].startswith("[DONE]"):
                    return out
                out.append(e)
            ev, data, retry, pending = None, [], None, False
            continue
        if line.startswith(":"):
            continue
        f, _, v = line.partition(":")
        if v.startswith(" "):
            v = v[1:]
        if f == "event":
            ev, pending = v, True
        elif f == "data":
            data.append(v); pending = True
        elif f == "id" and "\0" not in v:
            rid, pending = v, True
        elif f == "retry" and v and all(c in "0123456789" for c in v):
            retry, pending = int(v), True
    return out
