import random

class Replay:
    def __init__(self):
        self.calls = []
    def add_credit(self, credit_id, amount, timestamp, expiration):
        self.calls.append((timestamp, amount, timestamp + expiration))
    def subtract(self, amount, timestamp):
        self.calls.append((timestamp, -amount, None))
    def get_balance(self, timestamp):
        grants, debt = [], 0  # grants: [expires at, remaining]
        for ts, amount, end in sorted(self.calls):
            if ts > timestamp:
                break
            grants = [g for g in grants if g[0] >= ts]
            if amount > 0:
                paid = min(debt, amount)
                debt -= paid
                grants.append([end, amount - paid])
            else:
                need = -amount
                for grant in sorted(grants, key=lambda g: g[0]):
                    take = min(grant[1], need)
                    grant[1] -= take
                    need -= take
                debt += need
        value = sum(g[1] for g in grants if g[0] >= timestamp) - debt
        return None if value < 0 else value

def random_calls(rng, n, span=60):
    stamps = rng.sample(range(span), n)
    calls = []
    for i, ts in enumerate(stamps):
        if rng.random() < 0.55:
            calls.append(("add_credit", (f"g{i}", rng.randint(1, 9), ts, rng.randint(0, 25))))
        else:
            calls.append(("subtract", (rng.randint(1, 12), ts)))
    return calls

def call_ts(call):
    name, args = call
    return args[2] if name == "add_credit" else args[1]

class Amount(int):
    # An amount that counts the arithmetic and comparisons it takes part in; past the budget it raises.
    # Applying a call uses its amount a few times, so the count tracks how often calls are applied.
    uses, budget = 0, float("inf")
    def _use(self):
        Amount.uses += 1
        if Amount.uses > Amount.budget:
            raise AssertionError(f"amounts were used more than {Amount.budget} times")

def _counting(name):
    base = getattr(int, name)
    def method(self, *args):
        self._use()
        return base(self, *args)
    return method

for _name in ("__add__", "__radd__", "__sub__", "__rsub__", "__neg__", "__mul__", "__rmul__",
              "__lt__", "__le__", "__gt__", "__ge__", "__eq__", "__ne__", "__bool__"):
    setattr(Amount, _name, _counting(_name))
Amount.__hash__ = int.__hash__

for seed in range(150):
    rng = random.Random(500 + seed)
    calls = sorted(random_calls(rng, rng.randint(2, 20)), key=call_ts)
    late = [calls.pop(rng.randrange(len(calls))) for _ in range(rng.randint(0, 2))]
    ledger, model = {fn}(), Replay()
    for i, (name, args) in enumerate(calls):
        getattr(ledger, name)(*args)
        getattr(model, name)(*args)
        q = call_ts((name, args)) + rng.randint(0, 4)
        assert ledger.get_balance(q) == model.get_balance(q), (seed, q)
        if late and rng.random() < 0.3:
            extra = late.pop()
            getattr(ledger, extra[0])(*extra[1])
            getattr(model, extra[0])(*extra[1])
        if rng.random() < 0.2:
            back = rng.randrange(0, 70)
            assert ledger.get_balance(back) == model.get_balance(back), (seed, back)

import random

BEATS = [("Ember", "Bramble"), ("Bramble", "Tide"), ("Tide", "Spark"), ("Spark", "Ember")]

def slow_battle(team_a, team_b, smart=False):
    sides = [[team_a[0], [list(m) + [None] * (4 - len(m)) for m in team_a[1]]],
             [team_b[0], [list(m) + [None] * (4 - len(m)) for m in team_b[1]]]]
    log = [f"Match start: {team_a[0]} takes on {team_b[0]}"]
    turn = 0
    while True:
        attackers, defenders = sides[turn][1], sides[1 - turn][1]
        defender = [m for m in defenders if m[1] > 0][0]
        def power(m):
            if m[3] is None or defender[3] is None:
                return 1, ""
            if (m[3], defender[3]) in BEATS:
                return 2, " (2x)"
            if (defender[3], m[3]) in BEATS:
                return 0.5, " (0.5x)"
            return 1, " (1x)"
        def damage(m):
            return max(1, int(m[2] * power(m)[0]))
        alive = [m for m in attackers if m[1] > 0]
        attacker = alive[0]
        if smart:
            for m in alive:
                if damage(m) > damage(attacker):
                    attacker = m
        hit = damage(attacker)
        defender[1] -= hit
        line = f"{attacker[0]} hits {defender[0]} for {hit} damage{power(attacker)[1]}. "
        log.append(line + (f"{defender[0]} has {defender[1]} HP left." if defender[1] > 0 else f"{defender[0]} is defeated!"))
        if all(m[1] <= 0 for m in defenders):
            log.append(f"Match over: {sides[turn][0]} wins!")
            return log
        turn = 1 - turn

