import copy, random

def replicas(n):
    return [{fn}(site_id=chr(ord("A") + i)) for i in range(n)]

def deliver(target, op):
    target.apply(copy.deepcopy(op))  # as if it crossed the network

glyph = iter(range(0x4E00, 0x9FFF))
late_deletes = 0
for seed in range(150):
    rng = random.Random(seed)
    reps = replicas(3)
    queues = {(i, j): [] for i in range(3) for j in range(3) if i != j}
    placed = []  # (character, left neighbour or None, right neighbour or None) when typed
    seen = [set() for _ in reps]
    for round_ in range(40):
        for i, rep in enumerate(reps):
            if rng.random() < 0.5:
                continue
            before = rep.text()
            if not before or rng.random() < 0.6:
                index, ch = rng.randint(0, len(before)), chr(next(glyph))
                op = rep.local_insert(index, ch)
                assert rep.text() == before[:index] + ch + before[index:], "a local insert landed elsewhere"
                placed.append((ch, before[index - 1] if index else None, before[index] if index < len(before) else None))
                seen[i].add(ch)
                kind = ("insert", ch)
            else:
                index = rng.randrange(len(before))
                op = rep.local_delete(index)
                assert rep.text() == before[:index] + before[index + 1:], "a local delete removed another character"
                kind = ("delete", before[index])
            for j in range(3):
                if j != i:
                    queues[(i, j)].append((kind, op))
        for (i, j), queue in queues.items():
            if not queue or rng.random() < 0.5:
                continue
            k = rng.randint(1, len(queue))
            for (what, ch), op in queue[:k]:
                if what == "insert":
                    seen[j].add(ch)
                elif ch not in seen[j]:
                    late_deletes += 1
                deliver(reps[j], op)
                if rng.random() < 0.3:
                    deliver(reps[j], op)
            del queue[:k]
    for (i, j), queue in queues.items():
        for _, op in queue:
            deliver(reps[j], op)
    texts = [rep.text() for rep in reps]
    assert all(len(rep) == len(text) for rep, text in zip(reps, texts)), "len() must count a replica's visible characters"
    assert texts[0] == texts[1] == texts[2], (seed, texts)
    where = {ch: n for n, ch in enumerate(texts[0])}
    for ch, left, right in placed:
        if ch in where and left in where:
            assert where[left] < where[ch], (seed, "a character moved before its left neighbour")
        if ch in where and right in where:
            assert where[ch] < where[right], (seed, "a character moved after its right neighbour")
assert late_deletes > 50

import random, tracemalloc

class Model:
    def __init__(self, window):
        self.window, self.clock, self.events, self.seq = window, None, [], 0
    def record_event(self, user_id, chat_id, timestamp, event_type="ping"):
        if self.clock is not None and timestamp < self.clock - self.window:
            return
        self.seq += 1
        self.events.append((user_id, chat_id, timestamp, event_type, self.seq))
        self.clock = timestamp if self.clock is None else max(self.clock, timestamp)
    def recent_count(self, user_id, chat_id):
        if self.clock is None:
            return 0
        return sum(1 for u, c, ts, _, _ in self.events
                   if (u, c) == (user_id, chat_id) and self.clock - self.window <= ts <= self.clock)
    def active_sessions(self, user_id, now=None):
        if now is not None:
            self.clock = now if self.clock is None else max(self.clock, now)
        if self.clock is None:
            return 0
        active = 0
        for chat in {c for u, c, _, _, _ in self.events if u == user_id}:
            mine = [(ts, seq, kind) for u, c, ts, kind, seq in self.events if (u, c) == (user_id, chat)]
            pings = [(ts, seq) for ts, seq, kind in mine if kind == "ping"]
            closes = [(ts, seq) for ts, seq, kind in mine if kind == "close"]
            if pings and max(pings)[0] >= self.clock - self.window and (not closes or max(closes) < max(pings)):
                active += 1
        return active

def in_order_calls(rng, n, users="ab", chats="xyz", kinds=("ping",), gap=3):
    ts, calls = 0, []
    for _ in range(n):
        ts += rng.choice([0, 0, 1, 2, gap])
        calls.append((rng.choice(users), rng.choice(chats), ts, rng.choice(kinds)))
    return calls

def traced_peak_after(make_calls, tracker, checkpoints):
    # Current traced memory at each checkpoint (a count of calls made so far).
    tracemalloc.start()
    try:
        out = []
        for i, call in enumerate(make_calls):
            call(tracker)
            if i + 1 in checkpoints:
                out.append(tracemalloc.get_traced_memory()[0])
        return out
    finally:
        tracemalloc.stop()

for seed in range(300):
    rng = random.Random(seed)
    window = rng.choice([1, 2, 5, 9])
    tracker, model = {fn}(window), Model(window)
    assert tracker.recent_count("a", "x") == 0
    for user, chat, ts, _ in in_order_calls(rng, rng.randint(1, 40)):
        tracker.record_event(user, chat, ts)
        model.record_event(user, chat, ts)
        for u in "ab":
            for c in "xyz":
                assert tracker.recent_count(u, c) == model.recent_count(u, c), (seed, u, c, ts)

