import asyncio, random, sys, threading, time
from collections import Counter
from urllib.parse import urlparse

class Parser:
    def __init__(self, graph, delay=0.0, fail=()):
        self.graph, self.delay, self.fail = graph, delay, set(fail)
        self.calls, self.lock, self.inflight, self.peak = Counter(), threading.Lock(), 0, 0
    def get_urls(self, url):
        with self.lock:
            self.calls[url] += 1
            self.inflight += 1
            self.peak = max(self.peak, self.inflight)
        try:
            self.wait(url)
            if url in self.fail:
                raise ConnectionError(f"cannot load {url}")
            return list(self.graph.get(url, []))
        finally:
            with self.lock:
                self.inflight -= 1
    def wait(self, url):
        if self.delay:
            time.sleep(self.delay)

class GatedParser(Parser):
    # Every page but the start holds its call until `release` is set, so a crawl that
    # runs calls one at a time stalls there. The 5 s timeout only guards against a hang.
    def __init__(self, graph, start):
        super().__init__(graph)
        self.start, self.release, self.gave_up = start, threading.Event(), False
    def wait(self, url):
        if url != self.start and not self.release.wait(5):
            self.gave_up = True
            self.release.set()

class OverlapParser(GatedParser):
    # Releases the held calls once `need` of them are running together.
    def __init__(self, graph, start, need):
        super().__init__(graph, start)
        self.need = need
    def wait(self, url):
        with self.lock:
            if self.inflight >= self.need:
                self.release.set()
        super().wait(url)

def model_crawl(start, graph, fail=()):
    norm = lambda u: u.split("#", 1)[0]
    start = norm(start)
    host, seen, queue = urlparse(start).hostname, {start}, [start]
    while queue:
        url = queue.pop(0)
        links = [] if url in fail else graph.get(url, [])
        for link in links:
            link = norm(link)
            if urlparse(link).hostname == host and link not in seen:
                seen.add(link)
                queue.append(link)
    return sorted(seen)

def random_graph(rng, pages=25):
    bases = ["http://a.io", "https://a.io", "http://a.io:8080", "http://b.io", "http://sub.a.io"]
