import random

class Bad(Exception):
    pass

def model_run(program):
    n, pc, acc, seen = len(program), 0, 0, set()
    while True:
        if pc == n:
            return True, acc, None
        if pc < 0 or pc > n:
            raise Bad()
        if pc in seen:
            return False, acc, pc
        seen.add(pc)
        op, v = program[pc]
        acc += v if op == "add" else 0
        pc += v if op == "goto" else 1

SWAP = {"skip": "goto", "goto": "skip"}

def fixes(program):
    out = []
    for i, (op, v) in enumerate(program):
        if op in SWAP:
            p = list(program)
            p[i] = (SWAP[op], v)
            try:
                done, acc, _ = model_run(p)
            except Bad:
                continue
            if done:
                out.append((i, acc))
    return out

def random_program(rng, n):
    prog = []
    for i in range(n):
        op = rng.choice(["add", "skip", "goto", "goto"])
        v = rng.randint(-i, n - i) if op != "add" else rng.randint(-9, 9)
        if op == "skip" and rng.random() < 0.5:
            v = rng.randint(-20, 20)
        prog.append((op, v))
    return prog

def one_fix_programs(rng, count, lo, hi):
    out = []
    while len(out) < count:
        prog = random_program(rng, rng.randint(lo, hi))
        try:
            looped = not model_run(prog)[0]
        except Bad:
            continue
        found = fixes(prog) if looped else []
        if len(found) == 1:
            out.append((prog, found[0]))
    return out

class Counted(int):
    # A program value that counts the additions and equality checks it takes part in. pc and acc
    # built from it stay Counted, so the count measures the steps taken; past the budget it raises.
    ops, budget = 0, float("inf")
    @staticmethod
    def tick():
        Counted.ops += 1
        if Counted.ops > Counted.budget:
            raise AssertionError(f"more than {Counted.budget} steps")
    def __add__(self, other):
        Counted.tick()
        result = int.__add__(self, other)
        return result if result is NotImplemented else Counted(result)
    __radd__ = __add__
    def __sub__(self, other):
        Counted.tick()
        result = int.__sub__(self, other)
        return result if result is NotImplemented else Counted(result)
    def __rsub__(self, other):
        Counted.tick()
        result = int.__rsub__(self, other)
        return result if result is NotImplemented else Counted(result)
    def __eq__(self, other):
        Counted.tick()
        return int.__eq__(self, other)
    __hash__ = int.__hash__

def counted(program):
    return [(op, Counted(v)) for op, v in program]

def steps(budget, call):
    # The result of call, which must take at most budget steps on Counted values.
    Counted.ops, Counted.budget = 0, budget
    try:
        return call()
    finally:
        Counted.budget = float("inf")

def raises(name, call):
    try:
        call()
    except Exception as e:
        assert type(e).__name__ == name, f"expected {name}, got {type(e).__name__}: {e}"
        return e
    raise AssertionError(f"expected {name}, nothing was raised")

