    if level >= 3:
        ops += ["add_user", "add_file_by", "add_file_by", "add_file_by", "merge_user"]
    if level >= 4:
        ops += ["compress_file", "compress_file", "decompress_file", "decompress_file", "backup_user", "restore_user"]
    model, out = Model(), []
