    def walk(i, j, left, cells):
        if i == n - 1:
            out.append(list(cells)); return
        for c in (j - 1, j, j + 1):
            if 0 <= c < m and i + 1 < n:
                walk(i + 1, c, left, cells + [(i + 1, c)])
        if left and i + 2 < n:
            walk(i + 2, j, left - 1, cells + [(i + 2, j)])
    walk(0, p, k, [(0, p)])
    return out

