    v = [board[i][j] for i, j in path]
    s = sum(v)
    s += sum(x for t in range(1, len(v)) if v[t - 1] == v[t])
    s += sum(y for t in range(2, len(v)) if v[t - 2] < v[t - 1] < v[t])
    return s

