from torch.overrides import TorchFunctionMode

def nll_loop(p, M, Y):
    total = torch.zeros((), dtype=p.dtype)
    for i in range(Y.shape[0]):
        for a in range(Y.shape[1]):
            lab = Y[i, a].item()
            if lab < 0:
                continue
            q = p[i] @ M[a]
            total = total + -torch.log(q[lab] + 1e-8)
