    assert ctx.ndim == 2 and tgt.ndim == 2, (label, ctx.shape, tgt.shape)
    assert ctx.tolist() == want[0], (label, "context", ctx.tolist(), want[0])
    assert tgt.tolist() == want[1], (label, "target", tgt.tolist(), want[1])

